nice -n 19 ionice -c 3 python3 - <<'PEOF'
import json,glob,os
pick=json.load(open("/tmp/s0tr/pick.json"))
want={(a,b,c,d):e for a,b,c,d,e in pick}
D="/workspace/data/refe_navtrain"
found={}
for fp in sorted(glob.glob(D+"/onpolicy/sets/onpolicy_*.jsonl")):
    for ln in open(fp,encoding="utf-8"):
        if not ln.startswith("{"): continue
        i=ln.find('"log_name": "'); 
        r=None
        # cheap prefilter on token
        tk=ln[ln.find('"token": "')+10:][:16]
        if not any(k[1]==tk for k in want): continue
        r=json.loads(ln); k=(r["log_name"],r["token"],int(r["step"]),int(r.get("rank",0)))
        if k in want and int(r["ckpt_step"])==want[k]:
            if k not in found or (int(r.get("label_version",1))>=int(found[k].get("label_version",1))): found[k]=r
with open("/tmp/s0tr/sets/onpolicy_train64.jsonl","w") as f:
    for r in found.values(): f.write(json.dumps(r)+"\n")
tg={}
for fp in sorted(glob.glob(D+"/train_grow/targets_rank0.jsonl")):
    for ln in open(fp,encoding="utf-8"):
        if not ln.startswith("{"): continue
        r=json.loads(ln); k=(r["log_name"],r.get("token",""),int(r["step"]),int(r.get("rank",0)))
        if k in want: tg[k]=r
with open("/tmp/s0tr/train_grow/targets_rank0.jsonl","w") as f:
    for r in tg.values(): f.write(json.dumps(r)+"\n")
imgs=sorted({im for r in tg.values() for im in r["image"]})
open("/tmp/s0tr/imgs.txt","w").write("\n".join(imgs)+"\n")
print("found sets",len(found),"targets",len(tg),"imgs",len(imgs),flush=True)
PEOF
cd /workspace/data/navtrain_pixels
# map relative image path -> navtrain_current_N/<path>
nice -n 19 ionice -c 3 find . -maxdepth 1 -name 'navtrain_current_*' | sort > /tmp/s0tr/roots.txt
: > /tmp/s0tr/jpgs.txt
while read -r im; do for r in $(cat /tmp/s0tr/roots.txt); do if [ -f "$r/$im" ]; then echo "$r/$im" >> /tmp/s0tr/jpgs.txt; break; fi; done; done < /tmp/s0tr/imgs.txt
wc -l /tmp/s0tr/jpgs.txt /tmp/s0tr/imgs.txt
nice -n 19 ionice -c 3 tar cf /tmp/s0tr/pix.tar -T /tmp/s0tr/jpgs.txt
cd /tmp/s0tr && ls -la && sha256sum pix.tar sets/* train_grow/*
